import {topicChat} from './topic-chat.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function homePage(state,team){
  const topics=state.data.topics,topic=state.draftTopic??topics[0].title;
  return `<div class="page-heading"><div><h1>新建辩论</h1><p>确定辩题，选择双方角色。</p></div><button class="secondary" data-open-coach="topic">先练习</button></div><section class="debate-language-panel" aria-label="选择辩论语言"><div><strong>本场辩论语言</strong><p>辩题和问题可以用中文输入；选择英文后，双方发言、即兴回应和评审均使用英文。</p></div><div class="language-buttons" role="group" aria-label="辩论语言"><button type="button" data-debate-language="zh" aria-pressed="${state.language!=='en'}">中文辩论</button><button type="button" data-debate-language="en" aria-pressed="${state.language==='en'}">English · 英文辩论</button></div></section><div class="home-grid"><section class="topic-column">${topicChat(topic)}<details class="topic-examples" id="topic-examples"><summary>推荐辩题<span>6 个方向</span></summary><div class="topic-grid">${topics.map((t,i)=>`<button class="topic-card ${t.title===topic?'selected':''}" data-topic="${i}"><div><span class="category cat-${i}">${esc(t.category)}</span><span class="check">${t.title===topic?'✓':'↗'}</span></div><h3>${esc(t.title)}</h3></button>`).join('')}</div></details></section><aside class="setup-panel"><div class="section-heading"><h2>辩手</h2><button class="text-button" data-nav="roles">人物预设</button></div><div class="teams">${team('pro','正方','支持辩题','+')}${team('con','反方','反对辩题','−')}</div><p class="hint">2–6 位辩手，可分别指定模型。</p><div class="launch-bar"><div class="launch-options"><label class="sr-only">发言与评审语言 / Language<select id="debate-language" ${state.data.features?.english?'':'disabled'}><option value="zh" ${state.language!=='en'?'selected':''}>中文</option><option value="en" ${state.language==='en'?'selected':''}>English · 英文辩论</option></select></label><label>交锋轮数 <select id="rounds">${[1,2,3,4,5].map(n=>`<option ${n===(state.rounds||2)?'selected':''}>${n}</option>`).join('')}</select></label><label class="switch-label"><input id="research" type="checkbox" ${state.research!==false?'checked':''}> 联网检索</label><label class="switch-label"><input id="impromptu" ${state.data.features?.impromptu?'':'disabled'} type="checkbox" ${state.impromptu?'checked':''}> 即兴交锋${state.data.features?.impromptu?'':'（重启后启用）'}</label><label class="switch-label"><input id="autovoice" type="checkbox" ${state.autoVoice?'checked':''}> 自动朗读</label></div><label class="impromptu-question" ${state.impromptu?'':'hidden'}>即兴追问<textarea id="impromptu-prompt" maxlength="500" rows="2" placeholder="留空使用默认追问">${esc(state.impromptuPrompt||'')}</textarea></label><button class="primary" id="start" ${state.busy?'disabled':''}>${state.busy?'正在创建…':'开始辩论'} <span>→</span></button></div>${state.data.settings.provider==='demo'?'<p class="mode-note">演示模式使用示例内容。<button data-nav="settings">连接模型</button></p>':''}</aside></div>`;
}
